// CopyWebpackPlugin patterns that put the plugin schema files into
// `dist/schema/`. Used by webpack.config.ts.
//
// The patterns live here, outside the webpack config, so that the tests in
// scripts/__tests__ can run them without a build.
const fs = require('fs');
const path = require('path');

const ROOT = path.resolve(__dirname, '..');

// Generated by `go generate ./pkg/schema/...`.
const SETTINGS_SCHEMA_DIR = path.join(ROOT, 'pkg/schema');
const COMBINED_SCHEMA_PATH = path.join(SETTINGS_SCHEMA_DIR, 'schema.gen.json');

// Generated by TestQueryTypeDefinitions in pkg/promlib/models.
const QUERY_SCHEMA_DIR = path.join(ROOT, 'pkg/promlib/models/v0alpha1');
const QUERY_TYPES_PATH = path.join(QUERY_SCHEMA_DIR, 'query.types.json');
const QUERY_EXAMPLES_PATH = path.join(QUERY_SCHEMA_DIR, 'query.examples.json');

// The file that Grafana loads (pluginschema.NewSchemaProvider). Grafana does
// not read the per-part files under `schema/v0alpha1/`.
const COMBINED_SCHEMA_TO = './schema/v0alpha1.json';

// The dsconfig generator writes only the settings into schema.gen.json, so add
// the query types and the query examples here.
function addQuerySchemas(content) {
  const schema = JSON.parse(content.toString());
  for (const key of ['queryTypes', 'queryExamples']) {
    if (key in schema) {
      throw new Error(
        `schema.gen.json already contains "${key}". The generator now writes the query schema, so remove addQuerySchemas.`
      );
    }
  }
  schema.queryTypes = JSON.parse(fs.readFileSync(QUERY_TYPES_PATH, 'utf8'));
  schema.queryExamples = JSON.parse(fs.readFileSync(QUERY_EXAMPLES_PATH, 'utf8'));
  return JSON.stringify(schema, null, 2) + '\n';
}

const schemaCopyPatterns = [
  { from: path.join(SETTINGS_SCHEMA_DIR, 'dsconfig.json'), to: './schema/dsconfig.json' },
  { from: COMBINED_SCHEMA_PATH, to: COMBINED_SCHEMA_TO, transform: addQuerySchemas },
  { from: path.join(SETTINGS_SCHEMA_DIR, 'settings.gen.json'), to: './schema/v0alpha1/settings.json' },
  {
    from: path.join(SETTINGS_SCHEMA_DIR, 'settings.examples.gen.json'),
    to: './schema/v0alpha1/settings.examples.json',
  },
  // The two query files ship per-part, like the settings files. These patterns
  // also make webpack watch the files, so `npm run dev` runs addQuerySchemas
  // again when a query file changes.
  { from: QUERY_TYPES_PATH, to: './schema/v0alpha1/query.types.json' },
  { from: QUERY_EXAMPLES_PATH, to: './schema/v0alpha1/query.examples.json' },
];

module.exports = { COMBINED_SCHEMA_TO, addQuerySchemas, schemaCopyPatterns };
